import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import test from "node:test";
import { assessmentView } from "./assessmentData.js";
import { buildAnalysisReport, decodeReportText } from "./analysisReport.js";
import { buildReportDocument } from "./reportDocument.js";
import { buildEvidenceDisplayPlan, evidenceDisplayView, evidenceSourceHash, validateEvidenceDisplayPlan } from "./evidenceDisplayPlan.js";
import { evidenceRelationView } from "./evidenceRelations.js";

// Generated by the backend from synthetic requests, never an uploaded log.
const parity = JSON.parse(readFileSync(new URL("../../backend/tests/fixtures/evidence_display_plan_v3.json", import.meta.url)));
const copy = value => structuredClone(value);
const fresh = () => copy(parity);
const ref = (representative, ...related) => ({ role: "primary", representative_evidence_id: representative, related_evidence_ids: related });

test("v2 mixed references preserve both independent interpretations, classifications and role origins", () => {
  const { result, relations } = fresh(), before = JSON.stringify([result, relations]);
  assert.equal(evidenceRelationView(result, { ...relations, version: "evidence-relations-v1" }).invalid, true);
  const view = evidenceRelationView(result, relations);
  assert.equal(view.enabled, true); assert.equal(view.invalid, false);
  assert.deepEqual(view.rows.filter(item => item.supports !== "context").map(item => [item.evidence_id, item.supports]), [["e1", "attack_request"], ["e2", "normal_request"]]);
  assert.equal(view.rows[0].interpretation_ko, result.evidence[0].interpretation_ko);
  assert.equal(view.rows[0].related_sources[0].interpretation_ko, result.evidence[1].interpretation_ko);
  assert.deepEqual(view.rows[0].related_sources[0].origins, result.evidence[1].origins);
  assert.deepEqual(view.rows[1].roles, ["primary"]);
  assert.equal(JSON.stringify([result, relations]), before);
});

test("Python and JavaScript v3 display plans bind the same mixed references and role-local conditions", () => {
  const { result, relations, view } = fresh(), before = JSON.stringify([result, relations, view]);
  assert.equal(evidenceSourceHash(result, relations), view.plan.source_hash);
  assert.equal(validateEvidenceDisplayPlan(result, view.plan, relations), true);
  assert.deepEqual(buildEvidenceDisplayPlan(result, null, relations), view.plan);
  const displayed = evidenceDisplayView(result, view);
  assert.deepEqual(displayed.plan, view.plan);
  assert.deepEqual(displayed.core.map(item => [item.evidence_id, item.supports, item.interpretation_ko]),
    result.evidence.slice(0, 2).map(item => [item.evidence_id, item.supports, item.interpretation_ko]));
  assert.deepEqual(displayed.groups[0].related_sources.map(item => item.number), [2]);
  assert.deepEqual(assessmentView(result, { display: view }).issues[0].evidence_numbers, [1, 2]);
  assert.equal(JSON.stringify([result, relations, view]), before);
});

test("v2 required references keep their full transitive closure without hiding counter-evidence", () => {
  const { result, relations } = fresh();
  relations.groups = [ref("e1", "e3"), ref("e3", "e2")];
  const plan = buildEvidenceDisplayPlan(result, null, relations), view = evidenceDisplayView(result, {
    version: "evidence-display-view-v3", status: "completed", relations, plan,
  });
  assert.equal(validateEvidenceDisplayPlan(result, plan, relations), true);
  assert.deepEqual(view.groups[0].related_ids, ["e2", "e3"]);
  assert.deepEqual(view.groups.find(item => item.evidence_id === "e3").related_ids, ["e2"]);
  assert.ok(view.core.some(item => item.evidence_id === "e2" && item.supports === "normal_request"));
  assert.equal(view.groups.find(item => item.evidence_id === "e2").interpretation_ko, result.evidence[1].interpretation_ko);
  for (const id of ["e1", "e2", "e3"]) assert.ok(evidenceRelationView(result, relations).rows.some(item => item.evidence_id === id));
});

test("a bounded mixed cycle keeps both original claims rather than recursing or inventing a conflict", () => {
  const { result, relations } = fresh(); relations.groups = [ref("e1", "e2"), ref("e2", "e1")];
  const plan = buildEvidenceDisplayPlan(result, null, relations);
  assert.equal(validateEvidenceDisplayPlan(result, plan, relations), true);
  assert.deepEqual(plan.groups.slice(0, 2).map(group => group.related_ids), [["e2"], ["e1"]]);
  assert.deepEqual(evidenceRelationView(result, relations).rows.slice(0, 2).map(item => item.evidence_id), ["e1", "e2"]);
});

const malformedRelations = [
  value => { value.relations.version = "evidence-relations-v3"; },
  value => { value.relations.groups[0].role = "verifier"; },
  value => { value.relations.groups[0].related_evidence_ids = ["e99"]; },
  value => { value.relations.groups[0].related_evidence_ids = ["e1"]; },
  value => { value.relations.groups[0].related_evidence_ids = ["e2", "e2"]; },
  value => { value.relations.groups.push(copy(value.relations.groups[0])); },
  value => { value.relations.groups[0].interpretation_ko = "must not be rendered"; },
  value => { value.result.evidence[1].origins[0].index = 0; },
  value => { value.result.evidence[1].origins[0].index = "1"; },
  value => { value.result.evidence[1].origins[0].source_id = "c1000"; },
  value => { value.result.evidence[1].origins[0].role = "editor"; },
  value => { value.result.evidence[1].origins = []; },
];
for (const [index, corrupt] of malformedRelations.entries()) test(`v2 invalid source/role/reference ${index} falls back in full`, () => {
  const value = fresh(); corrupt(value);
  const view = evidenceRelationView(value.result, value.relations);
  assert.equal(view.enabled, false); assert.equal(view.invalid, true);
  const plan = buildEvidenceDisplayPlan(value.result, value.view.plan, value.relations);
  assert.equal(plan.status, "fallback");
  assert.deepEqual(plan.groups.map(group => group.member_ids), value.result.evidence.map(item => [item.evidence_id]));
});

test("mixed references never authorize an Editor merge of opposing classifications on the same source", () => {
  const { result, relations } = fresh();
  result.evidence[1] = { ...copy(result.evidence[0]), evidence_id: "e2", supports: "normal_request",
    origins: [{ role: "primary", index: 1, source_id: "c1" }] };
  const plan = buildEvidenceDisplayPlan(result, null, relations);
  assert.deepEqual(plan.groups.slice(0, 2).map(group => [group.member_ids, group.supports]), [[["e1"], "attack_request"], [["e2"], "normal_request"]]);
  const forged = copy(plan); forged.groups[0].member_ids.push("e2"); forged.groups.splice(1, 1);
  assert.equal(validateEvidenceDisplayPlan(result, forged, relations), false);
  const view = evidenceDisplayView(result, { version: "evidence-display-view-v3", status: "completed", relations, plan: forged });
  assert.equal(view.invalid, true); assert.equal(view.groups.length, result.evidence.length);
  assert.deepEqual(view.groups.map(item => item.supports), result.evidence.map(item => item.supports));
});

test("v3 exact grouping requires a located source and compatible dependencies, not merely equal prose", () => {
  const { result, relations } = fresh(); relations.groups = [];
  result.evidence[1] = { ...copy(result.evidence[0]), evidence_id: "e2",
    origins: [{ role: "verifier", index: 0, source_id: "c1" }] };
  let plan = buildEvidenceDisplayPlan(result, null, relations);
  assert.deepEqual(plan.groups[0].member_ids, ["e1", "e2"]);
  let view = evidenceDisplayView(result, { version: "evidence-display-view-v3", status: "completed", relations, plan });
  assert.deepEqual(view.groups[0].roles, ["primary", "verifier"]);
  assert.deepEqual(view.groups[0].member_sources.map(item => item.origins), result.evidence.slice(0, 2).map(item => item.origins));
  assert.equal(view.groups[0].interpretation_ko, result.evidence[0].interpretation_ko);
  delete result.evidence[0].source_spans; delete result.evidence[1].source_spans;
  plan = buildEvidenceDisplayPlan(result, null, relations);
  assert.deepEqual(plan.groups.slice(0, 2).map(group => group.member_ids), [["e1"], ["e2"]]);
});

test("a valid Editor-selected v3 representative remains an original explanation with unchanged member provenance", () => {
  const { result, relations } = fresh(); relations.groups = [];
  result.evidence[1] = { ...copy(result.evidence[0]), evidence_id: "e2", interpretation_ko: "A different original interpretation of the same synthetic source",
    origins: [{ role: "verifier", index: 0, source_id: "c1" }] };
  const plan = buildEvidenceDisplayPlan(result, null, relations);
  plan.status = "completed"; plan.reason = null;
  plan.groups[1].member_ids = ["e1", "e2"];
  plan.groups.splice(0, 1);
  plan.metrics.group_count -= 1; plan.metrics.core_group_count -= 1; plan.metrics.merged_count += 1;
  assert.equal(validateEvidenceDisplayPlan(result, plan, relations), true);
  const view = evidenceDisplayView(result, { version: "evidence-display-view-v3", status: "completed", relations, plan });
  assert.equal(view.groups[0].number, 2);
  assert.equal(view.groups[0].interpretation_ko, result.evidence[1].interpretation_ko);
  assert.deepEqual(view.groups[0].origins, result.evidence[1].origins);
  assert.deepEqual(view.groups[0].member_sources, view.items.slice(0, 2));
  assert.deepEqual(assessmentView(result, { display: { version: "evidence-display-view-v3", status: "completed", relations, plan } }).issues[0].evidence_numbers, [2]);
});

test("v3 grouping preserves same-role condition boundaries even for identical source and explanation", () => {
  const { result, relations } = fresh(); relations.groups = [];
  result.evidence[1] = { ...copy(result.evidence[0]), evidence_id: "e2", origins: [{ role: "primary", index: 1, source_id: "c1" }] };
  result.decision_issues[0].evidence_ids = ["e1"];
  const plan = buildEvidenceDisplayPlan(result, null, relations);
  assert.deepEqual(plan.groups.slice(0, 2).map(group => group.member_ids), [["e1"], ["e2"]]);
  assert.equal(validateEvidenceDisplayPlan(result, plan, relations), true);
});

test("equal source text with different dependency meanings cannot be merged by the Editor", () => {
  const { result, relations } = fresh();
  result.evidence[1] = { ...copy(result.evidence[0]), evidence_id: "e2",
    origins: [{ role: "primary", index: 1, source_id: "c1" }] };
  result.evidence[3] = { ...copy(result.evidence[2]), evidence_id: "e4", supports: "normal_request",
    origins: [{ role: "primary", index: 3, source_id: "c3" }] };
  relations.groups = [ref("e1", "e3"), ref("e2", "e4")];
  const plan = buildEvidenceDisplayPlan(result, null, relations);
  assert.deepEqual(plan.groups.slice(0, 2).map(group => group.member_ids), [["e1"], ["e2"]]);
});

test("a changed role-local condition invalidates the v3 map even when canonical evidence is unchanged", () => {
  const { result, relations, view } = fresh();
  result.primary.decision_issues[0].point_ko = "A different synthetic condition";
  assert.notEqual(evidenceSourceHash(result, relations), view.plan.source_hash);
  assert.equal(validateEvidenceDisplayPlan(result, view.plan, relations), false);
  assert.equal(evidenceDisplayView(result, view).plan.status, "fallback");
});

test("v3 web and offline reports preserve mixed classifications, original explanations and related source numbers", () => {
  const { result, relations, view } = fresh(), detail = { status: "completed", result, evidence_display: view };
  const before = JSON.stringify(detail), report = decodeReportText(buildAnalysisReport(detail));
  for (const item of result.evidence) {
    assert.ok(report.includes(item.excerpt));
    assert.equal(report.split(item.interpretation_ko).length - 1, 1);
  }
  assert.match(report, /근거 1 — 공격 요청 근거/); assert.match(report, /근거 2 — 정상 요청 근거/);
  assert.ok(buildReportDocument({ detail }).sections.length > 0);
  assert.equal(evidenceDisplayView(result, view, relations).invalid, false);
  assert.equal(JSON.stringify(detail), before);
});

test("a v3 view without a saved plan preserves the v2 links rather than changing the relationship contract", () => {
  const { result, relations } = fresh();
  const view = evidenceDisplayView(result, { version: "evidence-display-view-v3", status: "fallback", relations, plan: null });
  assert.equal(view.plan.version, "evidence-display-plan-v3");
  assert.equal(view.plan.status, "fallback");
  assert.deepEqual(view.groups[0].related_ids, ["e2"]);
  assert.ok(view.groups.every(group => group.default_visible && group.member_ids.length === 1));
});
